#include <stdio.h>
#include <limits.h>

int main(void) {
    int a = -1;
    unsigned int b = 1;
    printf("%d\n", a < b);               /* 0: a becomes UINT_MAX. */
    printf("%d\n", a < (int)b);          /* 1: compare as signed. */

    double avg = 7 / 2;                   /* 3.0: int division, then converted. */
    double ok = 7.0 / 2;                  /* 3.5. */

    long big = 3000000000L;
    if (big > INT_MAX || big < INT_MIN) { /* guard before narrowing. */
        puts("too large for int");
    } else {
        int small = (int)big;
        printf("%d\n", small);
    }
    printf("%.1f %.1f\n", avg, ok);
    return 0;
}
